const D = { density:.55, scale:1, energy:.65, speed:1, hue:32, tilt:.6, doppler:.7, x:.5, y:.5, style:'spacetime', act:'orbit', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const st = P.style;
const intn = (K.intensity!=null?K.intensity:0.6);
const wire=(st==='wire'), ink=(st==='ink'), irid=(st==='iridescent'), thermal=(st==='thermal');

// seed-dependent particle ring assignments
const MAXN = 200;
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  S.p = [];
  for (let i=0;i<MAXN;i++){
    S.p.push({ rf: Math.pow(fr(i*2+1),0.7), ph: fr(i*2+2)*6.283, jz: fr(i*3+5) });
  }
  S.streaks = [];
}

// -------- cached star / nebula background keyed on size+seed+style --------
const bgKey = width+'x'+height+'_'+P.seed+'_'+st;
if (!S.bg || S.bgKey!==bgKey){
  S.bg = createGraphics(width,height);
  const g=S.bg; g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  const cx=width/2, cy=height/2, mx=Math.max(width,height)*0.75;
  const paper=ink;
  const steps=60;
  for(let s=steps;s>=0;s--){
    const rr=mx*s/steps, f=s/steps;
    if(paper) g.fill(38,8-f*3,90-f*7,100);
    else if(wire) g.fill(206,50+f*25,12-f*7,100);
    else if(irid) g.fill(250,45+f*25,13-f*8,100);
    else g.fill(232,55+f*20,14-f*9,100); // deep space blue
    g.ellipse(cx,cy,rr*2,rr*2);
  }
  const nst=Math.floor((width*height)/4200);
  for(let i=0;i<nst;i++){
    const sx=fr(i*2+700)*width, sy=fr(i*2+701)*height, b=fr(i+1100);
    if(paper){ g.fill(35,16,42,26+b*36); g.ellipse(sx,sy,0.8+b*0.8,0.8+b*0.8); }
    else { const d=0.5+b*1.7; g.fill(b>0.9?42:210, b>0.9?25:14, 92, 18+b*70); g.ellipse(sx,sy,d,d); }
  }
  S.bgKey=bgKey;
}
image(S.bg,0,0);

// -------- accretion disk --------
const cx=P.x*width, cy=P.y*height;
const shadowR = u*0.11*P.scale;
const innerR = shadowR*1.28;
const outerR = u*0.44*P.scale;
// real-time vertical breathing of the whole disk: displaces a large band of pixels
// every frame and NEVER re-phases at the 8s gate (0.37 rad/s -> ~3 rad over 8s).
const squashBase = 0.10 + (1-constrain(P.tilt,0,1))*0.45;   // edge-on when tilt high
const squash = squashBase*(0.70 + 0.38*Math.sin(K.t*0.37 + 0.6));
const glow = 0.35 + P.energy*0.65 + A.rms*0.9 + 0.12*Math.sin(K.t*0.61); // gentle real-time swell
const dop = constrain(P.doppler,0,1);
const nP = Math.max(20, Math.round(MAXN*(0.25+P.density*0.75)));
const spd = P.act==='flare' ? P.speed*(0.5+intn*1.1) : (P.act==='calm'? P.speed*0.55 : P.speed);
const kick = K.pulse*0.5 + A.bass*0.85;

push();
translate(cx,cy);
rotate(0.11*Math.sin(K.t*0.083));   // slow real-time precession of the whole disk

if(!ink) blendMode(ADD);
if(wire){ noFill(); } else noStroke();

// draw disk particles (behind + in front of shadow both drawn; shadow occludes middle)
for(let i=0;i<nP;i++){
  const p=S.p[i];
  const rf=p.rf;
  const r=innerR + rf*(outerR-innerR);
  const w=0.9*Math.pow(innerR/r,1.5);        // Keplerian differential rotation
  const ang=p.ph + K.t*spd*w;
  const c=Math.cos(ang), s=Math.sin(ang);
  const px=c*r, py=s*r*squash;
  // doppler: approaching side (left, c<0) brighter+bluer; receding (right) dimmer+redder
  const beam = 1 + dop*0.95*(-c);
  const tHot = 1-rf;                            // inner = hot
  let hue = (P.hue + 26 - tHot*30 - (c>0?dop*22:-dop*10) + 360)%360;
  if(thermal) hue=(28 - tHot*28 + (c<0?18:0) +360)%360;
  if(irid) hue=(P.hue + rf*160 + K.t*10 + (c<0?40:0))%360;
  if(wire) hue=(196 + (c<0?-18:20))%360;
  const bri=(wire?0:(38+tHot*40)) + glow*30;
  const bright=Math.min(100, bri*beam*(0.7+p.jz*0.5) + kick*10*(1-rf));
  const alpha=(wire? 26 : (ink? 30 : 16+tHot*22)) * beam;
  const sz=(1.1 + tHot*2.2 + p.jz*1.2)*P.scale;
  if(wire){
    stroke(hue, 55, 80, alpha); strokeWeight(0.8);
    const ang2=ang+0.14; point(Math.cos(ang2)*r, Math.sin(ang2)*r*squash);
    line(px,py, Math.cos(ang2)*r, Math.sin(ang2)*r*squash);
  } else if(ink){
    fill(hue, 24, 18+tHot*10, alpha); ellipse(px,py,sz*0.9,sz*0.9);
  } else {
    fill(hue, thermal?90:(70-tHot*30), bright, alpha); ellipse(px,py,sz,sz*Math.max(0.5,squash*3));
  }
}

// -------- bright orbiting hot-clumps: real-time motion floor that breaks the
// disk's rotational symmetry. A few LARGE blobs travel around at K.t rate, so the
// aggregate image genuinely changes frame-to-frame (and across the 8s gate).
const nHot = 6;
if(!ink) blendMode(ADD); else blendMode(BLEND);
for(let i=0;i<nHot;i++){
  const rf = 0.20 + fr(i*7+31)*0.62;
  const r = innerR + rf*(outerR-innerR);
  const w = 0.9*Math.pow(innerR/r,1.5);
  const ang = fr(i*7+32)*6.283 + K.t*spd*0.55*w + K.t*0.22;   // real-time travel, incommensurate
  const c=Math.cos(ang), s=Math.sin(ang);
  const px=c*r, py=s*r*squash;
  const beam = 1 + dop*0.9*(-c);
  const tHot = 1-rf;
  let hue = (P.hue + 22 - tHot*26 - (c>0?dop*20:-dop*8) + 360)%360;
  if(thermal) hue=(30 - tHot*26 + (c<0?16:0) +360)%360;
  if(irid) hue=(P.hue + rf*150 + K.t*14 + (c<0?40:0))%360;
  if(wire) hue=(198 + (c<0?-16:22))%360;
  const bright=Math.min(100,(wire?60:52+tHot*34) + glow*26 + kick*10);
  const alpha=(wire?30:(ink?34:24))*beam;
  const sz=(6 + fr(i*7+33)*5.5)*(0.7+P.scale*0.5);
  if(wire){ stroke(hue,50,82,alpha); strokeWeight(1.2); noFill(); ellipse(px,py,sz,sz*Math.max(0.5,squash*3)); noStroke(); }
  else { fill(hue, thermal?92:(64-tHot*24), bright, alpha); ellipse(px,py,sz,sz*Math.max(0.5,squash*3)); }
}
blendMode(BLEND);

// event-horizon shadow (occludes disk mid-band -> leaves top rim arc + lower band)
noStroke();
if(ink){ fill(38,6,86,100); ellipse(0,0,shadowR*2.02,shadowR*2.02); fill(38,14,10,100); ellipse(0,0,shadowR*2,shadowR*2); }
else { fill(0,0,0,100); ellipse(0,0,shadowR*2,shadowR*2); }

// photon ring / lensed Einstein halo hugging the shadow (the over-the-top arc)
blendMode(ink?BLEND:ADD);
const ringR=shadowR*1.055;
const seg=90;
for(let i=0;i<seg;i++){
  const a=i/seg*6.283;
  const c=Math.cos(a);
  const beam=1 + dop*0.9*(-c);
  const hue= wire?196 : thermal?(30+(c<0?16:0)) : irid?((P.hue+K.t*12+ (c<0?40:0))%360) : ((P.hue+18 - (c>0?dop*20:-dop*8)+360)%360);
  const br=Math.min(100,(wire?70:66)*beam + glow*24 + kick*12);
  const al=(ink?55:34)*beam;
  const px=c*ringR, py=Math.sin(a)*ringR;   // near-circular halo (not squashed) -> arcs over top & bottom
  noStroke(); fill(hue, wire?45:(ink?20:60), br, al);
  const ps=(wire?1.4:2.2)+kick*1.5;
  ellipse(px,py,ps,ps);
}
blendMode(BLEND);

// infall streaks (spawned on bass/beat) spiral into the hole
if(!ink){
  const spawn = kick>0.5 || fr(Math.floor(K.t*7))>0.72;
  if(spawn && S.streaks.length<26){
    const a0=fr(S.streaks.length*13 + Math.floor(K.t*11))*6.283;
    S.streaks.push({a:a0, r:outerR*(0.7+fr(a0*9)*0.5), life:1});
  }
  blendMode(ADD);
  for(let i=S.streaks.length-1;i>=0;i--){
    const k=S.streaks[i];
    k.r -= (outerR*0.012)*(1+intn) + (shadowR/Math.max(k.r,shadowR))*4.5;
    k.a += 0.10*(1+ (innerR/Math.max(k.r,innerR)));
    k.life -= 0.012;
    if(k.r<=shadowR*1.02 || k.life<=0){ S.streaks.splice(i,1); continue; }
    const c=Math.cos(k.a), s=Math.sin(k.a);
    const x1=c*k.r, y1=s*k.r*squash;
    const x2=c*(k.r+outerR*0.05), y2=s*(k.r+outerR*0.05)*squash;
    const hue = irid?((P.hue+k.r*0.4)%360): thermal?46 : (P.hue+30)%360;
    stroke(hue, 55, 92, 45*k.life); strokeWeight((1+glow)*k.life);
    line(x1,y1,x2,y2);
  }
  blendMode(BLEND);
}
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
